declare(strict_types=1);require __DIR__.'/_init.php';try{if($_SERVER['REQUEST_METHOD']==='GET'){json_response(true,$pdo->query('SELECT t.*,a.name from_name,b.name to_name FROM transfers t JOIN warehouses a ON a.id=t.from_warehouse_id JOIN warehouses b ON b.id=t.to_warehouse_id ORDER BY t.id DESC LIMIT 200')->fetchAll());}require_role(['admin']);$d=request_json();$result=TransferService::create($pdo,$d,(int)$user['id']);json_response(true,$result,null,'',[],201);}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();json_response(false,null,'TRANSFER_REJECTED',$e->getMessage(),[],422);}catch(Throwable $e){api_error($e);}
